        "name": "财神爷",
        "rarity": "SP",
        "desc": "卡面：自从仙界也开始现代化建设后，财神爷就爱上了当西装暴徒的感觉。哪怕身姿挺括引得回头率百分百，他还是觉得都是在看他的钱。“诶，我怎么这么有钱。”\n技能：【我怎么这么有钱】财神爷不会亏待每一个信仰他的信徒。每使用一次增加100计划点，每个现实天限用一次，满2w计划点该技能自动销毁。\n【你怎么这么穷】不是财神爷的信徒容易穷运加身哦。随机沉默对方一次行动点。（pvp专用）\n【刷我的卡】财神爷上来就是一个掏黑卡的手势，全场他直接包下。商店购买物品是可通过骰子决定是否打折（在选定商品后），骰子结果成功打7折，失败原价。\n【福来】财神爷带来的从来都是正财运。幸运值少许提升，关卡中更容易获得线索，和npc交互提高掉落概率。被动技能，装备本身份卡自动启用。\n稀有度：sp\n特点：财神爷的信徒财运没差过。",
