        "name": "扫把星",
        "rarity": "SSR",
        "desc": "卡面：扫把星其实一直是个走在时尚前沿的男人，但不知道为什么追求的每一个女孩子都骂他晦气。虽然他出门总容易遇到事故，但他依旧坚信自己是幸运的。“我包幸运的，都是他们的错。”\n技能：【方便面没有叉子】因为方便面没有叉子太倒霉了这一天天什么破事，扫把星怨气很大。威慑指定人员获取线索，恐吓大成功。每关卡限定使用一次。\n【3456没有7】不是吧打牌扫把星也没有顺子，好吧，那就顺别人的。随机窃取别人一张卡牌，这一场为自己所用。（对锁定卡无效）\n【负负得正】扫把星喜欢跟同样倒霉的人在一起，这会让他觉得自己很幸运，也可以简称眉笔扎堆。和幸运值低的人在一起扫把星会幸运值+5，和幸运值高的人在一起扫把星会幸运值-5。被动技能，装备本身份卡自动启用。\n稀有度：ssr\n特点：真的很帅，但是眉笔。",
