        "desc": "卡面：为了响应新时代号召，城隍庙也开始了电子化办公，这可难为了岁数颇大的白胡子城隍爷爷，天天坐电脑面前使用一指禅急得团团转。“我什么时候才能录完文件啊！”\n技能：【城隍簿】城隍有一本厚厚的本子，用来记录该地人口的生老病死。轻轻在城隍薄上写上一笔，随机沉默一张对方已使用的卡牌。\n【地方父母官】城隍自古以来就是庇佑一方安乐的父母官，只要你遇到鬼怪，就可以寻求城隍帮助。天然被鬼怪厌恶，对低等级鬼怪有一定震慑力，不易被近身。被动技能，装备本身份卡自动启用。\n稀有度：r\n特点：爷爷真的学不会用电脑啊。",
