            "text": "卡面：锣鼓喧天，灯笼红缎。身着嫁衣的新娘乌发盘起，芙蓉出水。却不料有小人作祟，使她含恨而终。被缝住的红唇再也吐不出一声泣泪。\n“你我本同生，相煎何太急？”\n技能：\n【红颜薄命】新娘的脸是被活生生剥下来的，血色满地，唯有一对佳人死气洋洋。\n“你若心中无悔，又怎会畏我。”\n化大红妆的新娘面具佩戴到脸上时可魅惑交互的对象一次，交互者有问必答。每关卡只可使用一次。\n【簪叶红】新娘的陪嫁金簪，却在入馆时沾染",
