          "name": "诡灯",
          "rarity": "SR",
          "desc": "卡面：黑夜中总有漂浮在空中点点幽光，宛若萤火，煞是美丽。当你靠近，流着血泪的惨白脸庞会贴上你温热的脸。“不要，不要靠近。它会…吃了你！”\n技能：【同类】诡灯从来不独自出现，它们很喜欢和人类一起玩耍，直到…变成同类。随机获得一名敌方阵营玩家手上所有线索。每关卡可用一次。\n【新生】诡灯非常喜欢偷脸，这让他们仿佛有了生命。选定一个对象换脸（除脸以外其余不变），持续一个关卡天。每关卡可用一次。\n【诡物】诡灯源于活人被剥皮做成人皮灯笼，怨气极凶。天然被诡物亲近，更容易得到诡物中的线索。被动技能，装备本身份卡自动启用。\n稀有度：sr\n特点：有点亮，甚至可以当路灯\n制作者：策划",
