          "desc": "卡面：河水蜿蜒流淌，一个小小的女婴飘在水中。幼小的身体已经被河水泡的肿胀苍白，手臂的皮皱成一圈一圈……奇怪，她怎么在冲你笑。\n技能：【弃婴】村里每年祭祀需向河神供奉纯真幼童以求风调雨顺。爹娘为保哥哥抛弃了你，可作为祭品连上天都不收你。致命伤免疫一次，使用后将转化为鬼婴状态。\n【鬼婴】有人在河边洗衣时看见了你，大叫鬼婴回村了。他们用各种方法企图杀死你，却于事无补。被动技能，弃婴使用后触发。被人看见后概率降低对方san值，不分敌我。\n稀有度：R\n特点：她一直笑，一直笑。\n制作者：塞因",
