            "text": "卡面：淡绿色数据生成一只猫咪，黑色猫咪端坐着优雅的舔舐着毛发，碧绿色眸子闪过数据。“喵。”\n技能：【数据生成】黑猫生成的数据足以让末日颠倒。粉嫩色的猫爪垫按在虚空中，身上生成的数据演算着最佳算法，完美躲避来自外界的一切负面buff。pvp中免伤免控，副本中抵挡致命伤害。每次关卡只能使用一次。\n【数据模拟】使用后自动生成演算结果，更容易获得线索。被动技能，装备本身份卡自动启用。\n【数据重算】黑猫不耐",
