          "rarity": "SR",
          "desc": "卡面：渔夫帽，小板凳，一根鱼竿坐一天。这，就是我们钓鱼佬。“这儿有口，我今天包能钓到。”\n技能：【从不空军】钓鱼佬从不空军！除了鱼钓不上来什么都能钓上来。随机获取对方的卡包的一张卡牌（包括契约者卡牌），但自己不可使用。每场可用一次。\n【红温】钓鱼佬空军了就会红温。附加后伤害增加1（附加在ssr和sp卡上无效）。\n稀有度：SR\n特点：你可以说钓鱼佬人品不行，但不能说他钓不上来鱼。\n制作者：策划",
