          "desc": "卡面：西装革履，微分碎盖，这个男人是圈内出了名的帝王，也是你身边最深情的狗。他总是这样温温柔柔的看着你，一句话便让万千人难忍落泪。“af，我们都太骄傲。”\n技能：【逃吧挚爱】虽然难舍，他却仍然选择放你自由。免控一次，每关卡可使用一次。\n【想逃便逃】在你计划离开的时候，他早就为你铺好后路。+1血，第二次半价+0.5血，血量清零回合不可使用。每关卡可使用两次。\n稀有度：SR\n特点：还得是经典啊。",
