          "rarity": "SR",
          "desc": "卡面：一艘纯白色游轮航行在海面上，船头伫立着一尊张开双手的女神像，复仇女神号永远航行在自由海上。\n技能：\n【永无畏惧】女神号一往无前因为它永无畏惧。使用后将免疫控制技能及状态debuff类技能，伤害类技能会消减为一半。\n【复仇女神】复仇女神涅墨西斯认为不应该有人有过多的好运。使用后将标记最好运之人替自己承伤，全场骰点数字最高者将替伤（若总伤超过3滴血则只承伤3），若己方为最高则承伤一半。\n稀有度：SR\n特点：复仇女神代表着最无情的正义，一局只可以使用一次技能。\n制作者：帝昆",
