          "name": "大发明家",
          "rarity": "SR",
          "desc": "卡面：带着黑色帽子的人形站立在一张桌子后面，面前的桌子上摆着各类零件物品。\n技能：\n【创造】大发明家拥有绝对的创造性。使用后可以创造出一件副本内曾见过或有图纸或被仔细描述过的物品，存在时间为20min，自骰50失败则副本内npc发现，成功则npc会承认物品存在性。\n【灵感】大发明家需要大量的灵感脑洞。使用后可骰60灵感，成功则得到一条来自kp的信息提示或用来判断npc话语真实性，失败则无事发生。\n稀有度：SR\n特点：一场副本/对局只可使用一次。",
