          "name": "枫叶与眸",
          "rarity": "SR",
          "desc": "卡面：零落枫叶在空中飘散，血枫飘落遮挡住你的眼睛，眸底倒映着谁？\n技能：【红枫】\n思念汇集成红色枫叶，遮盖住视线，你的眼中皆是想念，使用后可指定一位玩家进行追踪，在接下来五段戏内知晓玩家所处位置。\n【倒映】\n眼里映着谁的模样，爱在眼波中流转万千，而那个人此刻正在治愈你，使用后倒映的人会获得一次免控buff，而自身会受到治疗1点。\n稀有度：SR\n特点：当思念具象化，你我皆是回忆。使用后情绪会放大数倍。\n制作者：烛",
