          "rarity": "SR",
          "desc": "卡面：蝴蝶振翅鳞粉翩翩落下，玫瑰在此刻绽放，而爱至死不渝。\n技能：【花开花落】\n花开不败，花落不悔，即使前行是深渊，而我们在此时便是永恒，使用后自身（或队伍）停止操作一回合，此回合伤害控制被吸收（debuff伤害也吸收），在下回合后将30％反还敌人。\n【命中注定】命运的红线在此缠绕，而你我，永不分离。使用后可与队友绑定，在此期间可获得队友获得的信息，道具等皆可以共享，而二人相遇时会获得一次回复血量1点。\n稀有度：SR\n特点：纯爱战士，只可与一个人绑定，更换他人本卡牌自动销毁。\n制作者：烛",
