            "text": "卡面：猫娘贴了过来，尾巴勾着你的手腕，竖瞳求助地看着你，而她的手中端着一杯咖啡，看起来香醇可口。\n技能：\n【猫娘女仆】长出猫耳猫尾，并且换上了女仆装，也可以听懂猫咪说话。被动技能，装备此身份卡自动启用。\n【您的咖啡～】提神醒脑的咖啡，pvp中自选免控一回合/回1滴血。pve中保持清醒头脑不会掉san和陷入混乱debuff两段戏\n稀有度：R\n特点：尾巴很灵活\n制卡师：眠海",
