          "desc": "卡面：穿着圣洁修女服的少女跪在神像前，手执十字架双目微阖，虔诚轻声祈福。\n技能：\n【净化】信仰祂的人需是纯净的…罪孽也会得到祂的宽恕，只要你诚心忏悔。使用后驱散自身污染5点，并在三段戏内不受任何debuff影响，但不能阻止自身被赋予debuff（免疫效果结束后新旧debuff皆继续生效）\n【纯洁】纯洁的少女，她拥有着主的庇护。更不容易被魔物邪物近身，被动，装备该身份卡自动启用。\n稀有度：R\n特点：虔诚\n制卡师：江听澜",
