          "name": "世界·永恒之舞",
          "rarity": "SSR",
          "desc": "牌面：世界女神悬浮于银河编织的圆环中，周身环绕着闪耀星辰，拜占庭风格金色长裙包裹她曼妙身躯，碎金流光自虚空划过，落在脚边化作十二道星轨，随她的呼吸明灭闪烁。“世界，由我主宰。”\n技能：【咏叹调】信徒最虔诚的祷告将化作咏叹调，赞美世界女神。一段悠扬的琴声后将破除对方此回合庇护效果（ssr卡及以下），pve中沉默对方最高等级庇护卡三段戏。\n【时空之影】她素白的手轻轻拨弄，世界便天旋地转。将时间拨回上一个回合的状态，技能状态不变，仅己方回溯，对方一切不变，不额外多加行动点。每场可用一次，cd5个自然天。\n【自然之音】华贵裙摆摇曳，诞生万万物。装备该卡所有技能cd减少一个自然天。被动技能，装备该身份卡自动启用。\n稀有度：SSR\n特点：所谓圆满，不过是万籁和鸣。\n制作者：策划",
