          "name": "神必据我",
          "rarity": "SP",
          "desc": "卡面：\n绫罗缠身，金线银丝织就云霞几重。彩绘傩面覆额，朱砂点额，青墨勾眉——霎时傩鼓裂空，神明借凡躯睁眼，垂眸人间。莲垂水面，月华在瓣间绽开。亭亭荷敛起千层花瓣，低垂若酣梦未醒。月光筛过薄云，碎在水波，银鳞万点，浮沉如禅。\n技能：\n【壹相·众生启途】\n“一舞一傩面，一念一众生。”\n战斗开始时，从以下三种“傩面”中选择一种获得核心增益，同时，根据所选面具，获得被动技能【神性低语】。\n〖喜相·福生〗\n造成的伤害使目标进入“破绽”状态，持续2回合。携带“破绽”的目标，受到的所有伤害（包括技能、普攻、真实伤害）额外增加25%。（pvp中为2点）\n【神性低语·喜】每次成功对“破绽”目标造成伤害，自身恢复造成伤害10%的生命值。(pvp中为1点)\n〖怒相·诛邪〗\n攻击时，有60%的概率(ra60)使目标陷入“惊惧”状态，持续1回合。“惊惧”状态下的目标无法行动(可使用庇护)，且下回合受到的首次伤害提升50%。\n【神性低语·怒】：当“惊惧”效果被抵抗时，立即对目标追加一次自身当前攻击力80%的必中伤害。(pvp中封顶为2.5血)\n〖悲相·渡世〗\n每当己方单位（包括自身）被击败时，为己方全体单位回复等同于自身攻击力120%的生命值，并驱散一个负面状态。仅在pve中生效。\n【神性低语·悲】：当己方单位生命值首次低于30%时，自动为其施加一个可吸收自身当前攻击力200%伤害的护盾，持续2回合（每场战斗每个单位仅触发一次）。\n【贰相·我相即妄】\n“凡所有相，皆是虚妄。”\n在【壹相·众生启途】的任一形态下，累计造成或承受4次攻击后，可主动激活此技能。每场战斗最多可使用两次。\n①破妄归元：立即清除自身所有负面状态，并获得一个持续1回合的“霸体”状态（免疫所有控制效果）。\n②神性临尘：立即获得之前未选择的两款【傩面】的核心效果（但不包括其【神性低语】），持续3回合。在此期间，你的所有攻击将随机附带这三种面具的基础特质（破绽、惊惧、全体回血）rd3决定附带的基础特质。\n③终末之祭：对敌方全体发动一次“审判”打击。总伤害为基础攻击力的180%（pvp中封顶4点），并根据敌方状态追加效果：\n对处于“破绽”的目标，额外造成一次其最大生命值8%的真实伤害（不超过自身攻击力的250%）（pvp中封顶1血）。\n对处于“惊惧”的目标，此次“审判”打击的伤害再提升50%（封顶总共4血）。\n对生命值低于30%的目标，直接斩杀（该效果对首领级敌人无效，但改为造成其最大生命值15%的真实伤害）。\n【终相·见神必】\n“若见诸相非相，即见……神必。”\n当【贰相·我相即妄】效果结束时，若你仍然存活，将进入“神必”状态（每场战斗仅触发一次）。\n神必降临：在战斗时获得所有三种【傩面】的核心效果及【神性低语】。\n傩面合一：自身所有技能冷却重置。在接下来的2回合内，你造成的所有伤害均为真实伤害，并且每次攻击都会使敌方全体随机陷入“破绽”、“惊惧”或“虚弱”（造成的伤害降低20%）中的一种状态。\n真我无相：此状态下，你无法被选中，也无法成为敌方技能的目标。\n稀有度：SP\n特点：NB，傩很帅。",
