          "name": "智齿",
          "rarity": "R",
          "desc": "卡面：一颗完美白色牙齿印刻牌面，只是底部微微泛红。哪怕沉默，它也自信自己的存在感无敌。\n技能：\n『智齿发炎』不声不响不注意，发起炎来要人命。pvp中可rd100后决定第几回合使用。若低于50强行沉默任意R卡该回合不生效；若低于30强行沉默任意SR卡该回合不生效；若低于10强行沉默任意SSR卡该回合不生效；若为1则强行沉默SP卡该回合不生效，同时炎症发作该回合自身也将选择沉默一张任意等级的卡牌不生效，每场可使用一次。\n稀有度：R\n特点：只有倒霉蛋才能使用的卡，越倒霉越好。\n制作者：帝昆",
