          "desc": "卡面：一个光头男人面朝这边，一手抬起做出邀请姿势，旁边还有个文字气泡“你的强，来了。”\n效果：【强哥请求验证】你的强来了，都说了强是最具有安全感的男人。使用后自身安全感爆棚，精神状态极好，理智值增加5点，或减少污染1点，使用一次碎一张。\n稀有度：N\n特点：可以和【你的福到了】卡牌合在一起使用，日常ra点增减5。\n制作者：帝昆",
