          "rarity": "SSR",
          "desc": "卡面：羽毛轻飘飘的落在这张卡面上，飘飘然若仙，卡面看起来轻盈极了。\n技能：【轻如鸿毛】轻如鸿毛，重于泰山。将当前生命值减少至1点并锁定，无法进行回血，下一回合获得损失hp一半的攻击力，并锁血状态解除，该部分攻击力无法吃到增益减益。每场可使用一次\n【重于泰山】轻如鸿毛，重于泰山。将当前自身受到的除【轻如鸿毛】外所有技能带来的攻击增益转化为临时生命值。该生命值存在两回合，同普通生命值一般使用，可享受回血效果。两个回合后消失，若剩余生命值大于1，则继续，若小于1，且不为0，则直接获胜。\n稀有度：SSR\n特点：这片羽毛，有千金之重。\n制作者：白鸽",
