            "text": "卡面：雾里伸出一只手，掌心躺着三枚硬币，在月光下泛着幽冷的银光。旁边的赌约时隐时现：“你要赌的是哪一应？”\n技能：【赌应】每一份筹码命运都已经暗中标注了价格。使用后此卡销毁。rd20随机获得以下效果\n结果为1，清醒： 下回合造成的所有伤害均为真实伤害（不受护盾影响）\n结果为8，假寐： 下回合自身无法被选中（仅针对指向性控制或者攻击）\n结果为15，沉睡： 下回合结束时，对敌方全体造成自身初始攻击力3",
