        "desc": "卡面：黑色的猫咪端坐在原地，抬爪舔食着自己的粉色肉垫，碧绿色的瞳孔映照着你的身影。\n技能：\n【加载中】\n黑猫数据生成中，汲取所有数据信息，加载中最优解，使用后黑猫可对最多3人发出攻击，每人伤害为1，不可叠加武器加成。\n【执行中】\n黑猫加载完毕，信息更新完成，使用后黑猫对敌方进行标记，接下来两个回合敌方所造成伤害减半，并为敌方施加紊乱debuff（骰子骰到3.4，敌方本次攻击伤害攻击到自己身上。）\n【计算中】\n黑猫眼中碧绿数据闪烁，启动后黑猫将自动装备到身份卡中，装备后更容易获得信息。\n稀有度：SSR\n特点：黑猫不容置疑。\n制作者：黑猫",
