        "name": "我不是盗神",
        "rarity": "SP",
        "desc": "卡面:整张卡的画面被斜分为1/2，左边的背景是高楼大厦的夜晚，其中溢出的灯光亮如白昼。一个白色西装男人侧身站立在顶楼，扬手用着同色的高沿礼帽向你鞠躬。右边是穿着黑裙的女孩，黑长直的头发与夜色巧妙融入在一起，你能看到她坐在顶楼上的腿不安分地前后摇晃。\n技能:\n【盗神的馈赠】:当你装备这张身份卡时，每天可进行一次对盗神的祈祷，有30%的概率掉落300计划点。ra30，小于30即可成功。\n【偷亦有道】:盗神认为，这个世界上的任何物品都可以被偷。使用后有50%几率可以盗取某人的随机记忆/道具/计划点/金币/菜/种子/好感等等（包括策划和npc）。\n特殊说明:1）记忆由个人拟定不同份数，使用者随机抽取，如果不想被偷盗记忆，可以给盗神≠使用者上交200计划点。npc可以给策划产出一张卡牌抵用此偷盗。若npc对你好感度≥35，则偷盗必定成功。2）道具按照玩家背包顺序任意抽取，偷窃npc道具可由npc自己产出。但稀有度由你的抽奖决定。rd100，0-10为sp，10-25为ssr，25-50为sr，50-70为r，70-100为n。3）计划点与金币偷盗数量在两位数到三位数中间，rd100，超过50即为3位数，但不超过300。rd300，出现数字即为偷盗数量。小于50即为两位数，rd99，出现数字即为偷盗数量。4）偷菜指定为田野里成熟未采摘的菜，种子为背包里某一样种子，数量为1/3。5）关于好感，可以偷窃npc对某玩家0-5点好感，rd5，出现数字即为偷窃数量。不过，要小心某玩家的好感可能是负数，当你偷到负数时，好感即为-5～0。\n冷却时间为三个自然日。但有20%的几率会被发现，如果遇到赫尔，该几率提升至50%。rd100，小于大于即可成功，遇到赫尔大于50即可成功。\n失败的代价，盗神并不知道，因为它从未失败过。\n【选择性失忆】:盗神的考虑当然是全面的——为了防止有谨慎的人发现自己丢东西了，盗神会让他们选择性失忆。当你成功窃取某样物品时，被偷盗的人会在当天忘记自己曾经拥有的物品，直到第二天才会恢复。\n【盗神的幸运】:百发百中的盗神当然需要一些运气。当你使用该技能时，你所有关于偷盗/欺骗类技能的概率均会提升10%。持续一天，冷却时间为五个自然日。\n稀有度:sp（动态卡）\n特点:一张特殊的身份卡，但盗神不喜欢运气不好的人。如果你使用这张卡牌技能时连续三次遭到失败，这张卡牌就会不翼而飞。\n制作者:赫尔",
