        "desc": "卡面：飘洋的白雪，五颜六色的小彩灯，属于月亮湾的热闹开场，一枚特殊的星星悬在卡牌中央，莹白色带着雪花碎纹的星星，欢迎你参与这场雪日狂欢。\n技能：\n【=• ֊ •=】它很嚣张，因为它拥有着特殊的附加效果，当你使用此技能时，可选择对准另一张需要进行判定的卡牌使用，使另一张需要判定的卡牌ra点上升10点。但使用此技能时需要先。rd10＞5，如果连续失败三次，星星会觉得很丢脸，它飞走了！同时请注意，本技能最多成功使用五次，五次后星星累了也会飞走啦…\n稀有度：sr\n特点：【雪日活动】特殊卡，玩家与契约者都可使用的卡牌。\n制作者：沙利叶",
