        "rarity": "SSR",
        "desc": "卡面：约莫一尺长的银色魔法杖上刻满复杂花纹，没有人知道这些花纹的含义，只知道魔法杖能给身份卡一些增益。\n效果：可选择身份卡进行增益加持。单体攻击技能增益50％伤害，群体攻击技能增益100％，回血类技能增益50％（不满0.5血按0.5血算）。生钱技能增益100％（最高可叠加三张本卡，仅生钱卡起效。按原始技能效果增益，选择生钱卡使用本卡则自动绑定不可拆卸），庇护类控制类技能不生效。pvp中每一场只能选择一张身份卡使用本卡，不可中途更换。\n分类：武器卡\n稀有度：SSR",
