          "desc": "卡面：日月相互照应，形成昼夜更替之景色，烛火在正中摇曳散发着微光。\n效果：\n【暮色】\n白昼消散余留暗色显盈，烛火在黑暗中明亮，月亮映照繁星闪烁。使用后敌方同等级卡牌产生的伤害减半，并为敌方覆盖穿透效果，下次攻击增加0.5，持续一回合，可根据卡牌成长。（随着等级提升附加伤害提升，每次提升0.5，升级至sp增加伤害1。）\n【白昼】\n暮色消弭所过之处便皆是新生，烛火光亮影影绰绰，日光之下无人能挡其光芒。使用后可使下次攻击带上灼伤伤害，附加0.5伤害。（随着等级提升附加伤害提升，每次提升0.5，升级至sp增加伤害1。）\n【隐藏被动·灼日之辉】\n需寻找特定之物升级其卡牌，升级成功后卡牌等级随之上升，每次升级都可吸收一次其他卡牌技能，ra30成功可吸收该卡牌两个技能。\n【SP·日月同辉】未知\n稀有度：R\n分类：技能卡\n特点：没有实体。\n制作者：烛",
