          "rarity": "SSR",
          "desc": "卡面：若说萝莉是死宅的天堂那御姐必然是魅魔。胸大腰细，貌美肤白的御姐穿着制服装，看你的眼神风情万千，也似有若无。\n效果：其实手办是不存在的哟，这一切只是宅男的幻想。你惹怒了宅男，他燃烧了自己。在pvp最后一个回合使用时伤害x1.5（翻倍后上限4血）如果并未终结对手，则反噬3点伤害。\n分类：技能卡\n稀有度：SSR\n特点：集齐该套卡可找策划兑换一个手办道具。",
