          "rarity": "SP",
          "desc": "卡面：四四方方且简单的小房间里只有一扇高高的窗，墙壁上挂着空白画像，房间中心放置着两套白色桌椅，除此之外再无其他。\n效果：将双方所有人（上限4）拉入忏悔室，持续3个回合。pvp中强制对方忏悔不做任何伤害人的行为一回合，而后己方伤害增益每个回合1血，若有技能处于cd中，将立即刷新cd最短的一个技能。pve中则对方沉默两段戏且有r2d10的血量转化为己方血量，并刷新己方一个cd最短的技能。每场仅可使用一次。\n分类:地图卡\n稀有度：SP\n制作者：策划",
