            "text": "卡面：恕山之云骨，环蔽天水，水多怪兽，赤人行谷，几言恠者皆谓其状渠奇，貌若福鲤，鳞生四彩，五尾哗然，额凸双角，琉璃煞粹，腹尾透骨，音唤好女，如幻如此，名曰姝杹，断琉璃角以萃尘，姝杹骨烹味之食，食之明目，澄心祛疾，多子多孙。\n效果：姝杹需消耗琉璃角发动技能，初始携带四枚琉璃角。每场PVP/副本仅可补充一次琉璃角，若琉璃角全部碎裂则进入【失明】状态。（全部用完当前回合内PVP里为己方对敌方伤害－1，副",
