          "desc": "卡面：一只小白兔，耳朵长又长。以胡萝卜为诱饵，可唤兔灵来附身。\n效果：白兔的耳朵可以让它获得很多信息。pve中可获取一条线索，不限真假，具体根据kp判定。\n特点：被附身后会长出兔耳朵和兔尾巴哦。\n分类：技能卡\n稀有度：R\n制作者：策划",
