          "name": "抱歉我雷波浪号",
          "rarity": "SR",
          "desc": "卡面：满屏的波浪号飘在空中，五颜六色的。\n效果：当你使用这张卡的时候，请用冷酷的语气说出：“说出抱歉我雷波浪号，判断我在不在请看50条前我有没有出现，有时候只是在窥屏；歉退。”对手会因为你的这段话沉默一回合无法使用任何技能。可被庇护抵消。每场可使用一次。\n分类：技能卡\n稀有度：SR\n制作者：赫尔",
