          "name": "四时有序",
          "rarity": "SP",
          "desc": "卡面：卡牌少有的正面与背面都有图案，春夏秋冬四季轮转在其中。\n春日带着翠鸟与微风浮现在卡面之上，暖黄色的迎春缓慢绽开花瓣，与生俱来的温柔容纳了万物。\n夏季带着蝉鸣与烈日彰显在你面前，粉色的荷花在水面上袅娜娉婷，喧嚣热闹的氛围感染着世界。\n秋天带着果实与落叶倒印在你眼底，金黄色的麦穗弯腰亲吻着地面，梧桐苍苔的寂寥铺满着台阶。\n冬色带着寒雪与冷冽占据视觉神经，月白色的雪花缓浮飘荡无踪迹，无处不在的柔软却锋利如刀。\n效果：\n【春和景明】\n若叠满三层花苞护盾，护盾血量默认为真实血量。\n护盾若低于1，按照1血量扣算。\n[春风徐来]春风徐来，春枝欲绽放。\n使用后基于自身所损失的最大生命40%（低于两点获得两点），获得一层花苞护盾。\n[春光作序]春光作序，万物尽和鸣。\n使用后恢复自身.rd4#5血量（pvp获得2点），若拥有护盾则恢复自身.rd5#5血量（pvp获得3点）。若放弃回血则获得一次花苞护盾（自身当前拥有血量最高30%生命的护盾，低于两点获得两点）。每场对局只能使用一次。\n[春与人宜]春与人宜，好事正佳酿。\n使用后可使自身免于受debuff侵扰持续三回合（包括但不限于持续伤害，负面效果等），在挂上控制类型debuff时会自动释放，未拥有debuff获得一次花苞护盾（自身当前拥有血量最高30%生命的护盾，低于两点获得两点）。每场对局只能使用一次。\n【夏日人间】\n[夏日初长]夏日初长，且听风吟。\n使用后燃烧自身基础生命值10%（花苞护盾可与基础血量一同扣算，优先扣除护盾血量），获得150%攻击（pvp最高4点）。cd5个自然天。\n（例如基础血量为10，使用清风徐来或任意可生成花苞护盾技能后获得4点护盾，那么玩家初始血量为14点，扣除10%就是1.4获得的伤害为150%，伤害为2.1）\n[花开半夏]花开半夏，留我须臾。\n使用[夏日初长]后三回合内受到敌方攻击时，超出2名敌人后，每多存在一名敌人，则以本回合自身攻击力为基础，造成的反伤多增加10％（比如自身攻击力为5，场上有3名敌人，则造成的反伤最终为敌人造成的伤害＋0.5），且被控时同样生效（机制同庇护）。每场对局只能生效一次。\n【天下知秋】\n[秋色见晚]秋色见晚，霜报黄花。\n使用后本回合对任意两名敌方造成30%伤害，可额外在下一回合获得一次行动点，该行动自动添加‘贯穿伤害’增益buff，伤害增加20%，且贯穿伤害无法被格挡，无视防御和减伤效果，同时该次行动将不再受其他增益效果影响。每场对局只能使用一次。\n[潇湘秋影]潇湘秋影，远山黛色。\n若上回合使用过该卡牌后，从本回合开始计算，每回合增加20%攻击伤害，最多可叠加五层，使用任意一次其他卡牌后增加值归零，且不可在额外行动中使用。\n【岁暮天寒】\n[苍山负雪]苍山负雪，明烛天南。\n使用后获得范围性领域，在此领域期间敌方‘迟缓’一回合，且附加一层‘冰霜’。每场对局只能生效一次。\n（迟缓：敌方本回合行动所造成的伤害，血量或者buff等，皆下一回合自身轮次时生效。）\n[夜雪初霁]夜雪初霁，烧灯续昼。\n使用后可造成无视敌我范围性冰冻，在该冰冻期间，所受伤害无效，若敌方身上有一层冰霜，则形成冻伤debuff，下回合伤害在原基础上增加20%（pvp最多增加2点）每场对局只能生效一次。\n稀有度：sp\n分类：地图卡\n特点：为动态画面卡牌效果，在卡牌禁止使用时会呈现为灰色，每次该卡牌只能和同系列春夏秋冬中的任意两张同时存在。\n每满两层护盾为一次增益buff，未满两层按照一次增益buff计算。\n制作者：烛",
