            "text": "卡面：一个人影分身成五个身形一模一样的虚影，全都盖着红色盖头。\n效果:\n【怎么会有这么巧的事】当你受到单次伤害时，可以召唤五个虚影，你可以选择任意一个虚影寄宿。当对面攻击时需要在1-5中选择一个虚影，虚影受到攻击就碎，四回合后无论是否受到攻击都全部消失。虚影存在期间可以持续搅浑水，对面接下来的三次攻击（不论虚影是否存在）都需要。ra75看是否成功，因为虚影“无法选中”。\n【清者自清】人不要脸天下无",
