        "desc": "卡面：亘古，悠久，所以成物也。幽幽深红火焰凝聚成珠，靠近便会被灼伤。\n效果：\n【赩焰】\n赩焰凝聚成火焰时，在无主状态下并不可主动攻击，但火精不可侵犯，自围绕凝聚成火焰护罩，灼烧袭来所有的异常，免控一回合（可被动解控）且驱散当回合自身的debuff，包括灼伤，持续伤害等。仅使用一次。\n【耀阳】\n凡人不可直视太阳，自升起之时光辉便不可抗拒。使用后会控制敌方一回合，控制成功后可使敌方下一回合伤害减半。每场仅使用一次。\n【衔珠】\n火精吞咽入喉，灼痛侵蚀你的全身，相同的你所发出的攻击增强了，使用后自身本回合扣除0.5滴血，此次攻击伤害为2。每场仅使用一次。\n分类：武器卡\n等级：SP\n特点：烛专属卡牌。\n火精为不可认主之物，过度控制会造成反噬污染。\n制作者：烛",
