        "name": "元宝·月眠",
        "rarity": "SR",
        "desc": "卡面：今晚的月亮很亮，你看见了吗？在月亮的边缘，明亮的月光被柔软的绒毛覆盖，透出丝丝缕缕的光——元宝抱着月亮，它将月亮团在怀里，在这里沉睡着…\n技能：\n【月眠】它睡着了…暂时的。在这片月光洒落的地方，所有敌对方将停止行动并被迫陷入沉睡，此时双方都无法进行攻击，请离开这里吧，月光会为你照亮安全的道路，持续三回合。\n【月临】这是一片，月光的碎片，它是眼泪…输入。rd100，当：\nrd100＝（1-50）时，获得一片月光碎片；\nrd100＝（51-100）时，获得两片月光碎片，\nrd100＝15，19，33，23时，获得三片月光碎片。\n在普通hp为100时，一片月光碎片可＋15hp，在PVP时，一片月光碎片＋1心。\n当你骰出15、19、33、23几个数字时，元宝会苏醒，此时三片月光碎片将作为攻击手段，此卡的【月临】暂时提升至ssr等级强度。\n【月临·特殊】ssr效果\n这是一个特殊的时间，属于小猫的时间在此停滞。碎片可分不同回合使用，第一片碎片攻击，对方hp为100时，－20hp。PVP时，－1.5心；第二片碎片攻击，对方hp为100时，－15hp。PVP时，＋自身1.5心；第三片碎片攻击，对方hp为100时，－10hp。PVP时－1心。当此技能碎片全部用完后，普通pve里将沉默对方两段戏；PVP里如果你是先手方则沉默对方一回合，如果你是后手方将免疫本次伤害的40%（不足1按1算）。本技能不受其他ssr及以下卡牌的限制。\n稀有度：sr（ssr）\n特点：【月临·特殊】最多使用三次，三次用完后将不会再触发此技能。此卡为玩家与契约者都可使用的卡牌。这是一张纪念卡，使用时请。ra60成功则可启用，晚安元宝。\n制作者：沙利叶",
